```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) client_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,2) server_p50_ms, round(avg((epoch_ns(s.time)-epoch_ns(c.time))/1e6),1) avg_start_gap_ms, round(avg(((epoch_ns(c.time)+c.duration)-(epoch_ns(s.time)+s.duration))/1e6),1) avg_end_gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name IN ('frontend','search') GROUP BY 1,2 ORDER BY 1,2",
          "claim": "search→rate client p50 is 2323ms while rate server p50 is 0.12ms; the gap is before the server span starts (~2250ms), not after it."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name AS svc, span_name, attr_span_kind kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('search','rate') GROUP BY 1,2,3 ORDER BY 1,2",
          "claim": "search's own server span and search→geo calls stay fast while search→rate calls stall at about 4s p95."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name pod, count(*) n, round(avg(value),3) avg_v, round(max(value),3) max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'search%' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.container.restarts') GROUP BY 1,2",
          "claim": "search pod CPU, memory and restart counter stay flat during the incident, so the pod itself is not saturated or restarting."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) client_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,2) server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='frontend' AND s.service_name='search' GROUP BY 1,2",
          "claim": "frontend's client calls to search take about 2324ms at p50, matching search's server time, so the delay passes up to frontend."
        }
      ]
    }
  ]
}
```

